class Solution {
public:
    std::vector<int> numOfBurgers(int tomatoSlices, int cheeseSlices) {
        int diff = tomatoSlices - 2 * cheeseSlices;
        if (diff < 0 || diff % 2 != 0) return {};
        int jumbo = diff / 2;
        int small = cheeseSlices - jumbo;
        if (small < 0) return {};
        return {jumbo, small};
    }
};

class Solution {
    public java.util.List<Integer> numOfBurgers(int tomatoSlices, int cheeseSlices) {
        int diff = tomatoSlices - 2 * cheeseSlices;
        if (diff < 0 || diff % 2 != 0) return java.util.List.of();
        int jumbo = diff / 2;
        int small = cheeseSlices - jumbo;
        if (small < 0) return java.util.List.of();
        return java.util.List.of(jumbo, small);
    }
}

var numOfBurgers = function(tomatoSlices, cheeseSlices) {
    const diff = tomatoSlices - 2 * cheeseSlices;
    if (diff < 0 || diff % 2 !== 0) return [];
    const jumbo = diff / 2;
    const small = cheeseSlices - jumbo;
    if (small < 0) return [];
    return [jumbo, small];
};
